"""Shared constants for the `rasa tools` CLI command family.

Duplicated from `rasa.builder.copilot.*` to avoid importing heavy
dependencies at CLI startup.  Keep these in sync when updating.
"""

import re
from typing import Dict, Tuple

from prompt_toolkit.styles import Style

# MCP server defaults ==================================================================

MCP_TOOLS_DEFAULT_PORT = 7331
MCP_TOOLS_DEFAULT_HOST = "127.0.0.1"
MCP_TOOLS_TRANSPORT_STDIO = "stdio"
MCP_TOOLS_TRANSPORT_HTTP = "http"
MCP_TOOLS_TRANSPORT_STREAMABLE_HTTP = "streamable-http"
MCP_TOOLS_RASA_PROJECT_FOLDER_ENV_VAR = "RASA_PROJECT_FOLDER"
MCP_TOOLS_HTTP_URL_PATTERN = "http://{host}:{port}/mcp"
MCP_TOOLS_HTTP_HEALTH_URL_PATTERN = "http://{host}:{port}/health"

# Codex defaults to 60s per MCP tool call, which is too short for long-running
# tools like train_rasa_assistant.  These overrides are written into the Codex
# project config so those tools don't time out.
CODEX_TOOL_TIMEOUT_SEC = 120
CODEX_STARTUP_TIMEOUT_SEC = 30

# Must match the default Rasa server URL (see DEFAULT_SERVER_PORT in
# rasa/core/constants.py).
DEFAULT_RASA_SERVER_URL = "http://localhost:5005"

# IDE support ==========================================================================

SUPPORTED_IDES: Tuple[str, ...] = ("cursor", "vscode", "claude", "jetbrains", "codex")

# Base directory within the project root where each IDE loads skills from.
# Layout: <base>/<skill-name>/SKILL.md plus optional files under references/.
IDE_SKILLS_BASE: Dict[str, str] = {
    "cursor": ".cursor/skills",
    "vscode": ".github/skills",
    "claude": ".claude/skills",
    # JetBrains has no standard skills location.
    # Codex uses skills.config in config.toml — skills are referenced by path.
    "codex": ".codex/skills",
}

IDE_DISPLAY_NAMES: Dict[str, str] = {
    "cursor": "Cursor",
    "vscode": "VS Code (GitHub Copilot)",
    "claude": "Claude Code",
    "jetbrains": "JetBrains IDEs (IntelliJ, WebStorm, PyCharm, etc.)",
    "codex": "OpenAI Codex",
}

# Tools config =========================================================================

TOOLS_CONFIG_DIR = ".rasa"
TOOLS_CONFIG_FILENAME = "tools.yaml"

# Offline docs fetching ================================================================

DEFAULT_LLMS_TXT_BASE_URL = "https://rasa.com/docs"
LLMS_TXT_BASE_URL_ENV_VAR = "RASA_LLMS_TXT_BASE_URL"

RASA_TOOLS_PROXY_BASE_URL_ENV_VAR = "RASA_TOOLS_PROXY_URL"

HTTP_TIMEOUT = 30
LLMS_TXT_FILES: Tuple[str, ...] = ("llms.txt", "llms-full.txt")

# Mantle offline docs fetching =========================================================

# Mantle docs live on their own site, so they get their own base URL and env override.
# Reusing the CALM ones would let a CALM docs mirror silently redirect Mantle fetches
# to a host that serves no Mantle content.
# Also MANTLE_DOCS_SITE.base_url in rasa/builder/document_retrieval/mintlify.py.
DEFAULT_MANTLE_LLMS_TXT_BASE_URL = "https://rasa-2f7eb63d.mintlify.site"
MANTLE_LLMS_TXT_BASE_URL_ENV_VAR = "RASA_MANTLE_LLMS_TXT_BASE_URL"

# Deliberately a subdirectory of the config dir rather than the config dir itself:
# `rasa tools init` writes the CALM bundle to `.rasa/` under the same two filenames.
# Sharing the directory would make whichever command ran last overwrite the other's
# docs, and would make the CALM "offline docs detected" warning fire on Mantle
# projects.
MANTLE_DOCS_SUBDIR = "docs/mantle"

# Calm agent-skills GitHub fetch (pre-manifest path) ===================================

AGENT_SKILLS_REPO = "RasaHQ/rasa-agent-skills"
AGENT_SKILLS_API_URL = "https://api.github.com/repos/{repo}/contents/skills"
AGENT_SKILLS_REFERENCES_API_URL = (
    "https://api.github.com/repos/{repo}/contents/skills/{skill}/references"
)
AGENT_SKILLS_RAW_URL = (
    "https://raw.githubusercontent.com/{repo}/main/skills/{skill}/SKILL.md"
)
AGENT_SKILLS_REFERENCE_RAW_URL = (
    "https://raw.githubusercontent.com/{repo}/main/skills/{skill}/references/{filename}"
)
AGENT_SKILL_ENTRYPOINT = "SKILL.md"
AGENT_SKILL_REFERENCES_DIR = "references"

# Skills bundled inside the wheel as package data, laid out as
# ``<BUNDLED_SKILLS_DIRNAME>/<engine>/<skill>/SKILL.md`` next to this package.
# Mantle skills match the running Rasa version by construction and install
# offline.
BUNDLED_SKILLS_DIRNAME = "skills_data"

# Engines ==============================================================================

ENGINE_CALM = "calm"
ENGINE_MANTLE = "mantle"
SUPPORTED_ENGINES: Tuple[str, ...] = (ENGINE_CALM, ENGINE_MANTLE)

# Wizard UI style ======================================================================

WIZARD_STYLE = Style(
    [
        ("qmark", "fg:ansicyan bold"),
        ("question", "bold"),
        ("answer", "fg:ansigreen bold"),
        ("pointer", "fg:ansicyan bold"),
        ("highlighted", "fg:ansicyan bold"),
        ("selected", "fg:ansigreen"),
    ]
)

# Agent skills helpers =================================================================

AGENT_SKILL_FRONTMATTER_RE = re.compile(r"^---\s*\n(.*?)\n---", re.DOTALL)
AGENT_SKILL_RASA_VERSION_RE = re.compile(r"rasa_version:\s*[\"']?([><=!~]*)([\d.]+)")
# Capture the full scalar so invalid values (e.g. `version: "3.x"`) are seen
# in their entirety and can be rejected, instead of mis-parsing them as `3.`.
AGENT_SKILL_VERSION_RE = re.compile(r"(?<!rasa_)version:\s*[\"']?([^\s\"'\n]+)")
AGENT_SKILLS_VERSION_SPECIFIER_PREFIX_RE = re.compile(r"^([><=!~]+)?\s*(.+)$")
